ndex={{page}}&pagesize=21&tagid=34&status=0&sort=10\"}","header":"{\n\"User-Agent\":\"Mozilla/5.0 (Linux; Android 11; PCLM10 Build/RKQ1.200928.002; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/93.0.4577.62 Mobile Safari/537.36\"\n}","loginUrl":"","ruleExplore":{"author":"Author","bookList":"UpdateComicItems","bookUrl":"http://www.mangabz.com/{{$.UrlKey}}","coverUrl":"ShowConver","intro":"Content","kind":"","lastChapter":"ShowLastPartName","name":"Title","wordCount":"LastUpdateTime"},"ruleSearch":{"author":".manga-item-subtitle.0@text","bookList":".manga-list@a","bookUrl":"a@href","coverUrl":"img@src","intro":".manga-item-content@text","kind":".manga-item-subtitle@span@text","name":".manga-item-title@text"},"ruleBookInfo":{"author":".detail-main-subtitle.0@text","init":"","name":".detail-main-title@text"},"ruleToc":{"chapterList":"-class.detail-list@a","chapterName":"text","chapterUrl":"href","updateTime":""},"ruleContent":{"content":"@js:\r\ntry{\nheaders={\"headers\":{\"Referer\":baseUrl}};\r\neval(result.match(/(eval\\([\\s\\S]+?)<\\/script/)[1]);\r\nnewImgs.map(a=>\r\n'<img src=\"'+a+','+JSON.stringify(headers)+'\">').join(\"\\n\")\r\n}catch(e){}","imageStyle":"FULL"}},{"bookSourceName":"曼哈漫画","bookSourceUrl":"https://mangadex.org","bookSourceGroup":"漫画 书源","bookSourceComment":"","bookSourceType":2,"searchUrl":"@js:\neval(String(source.loginUrl));\nresult = `https://api.mangadex.org/manga?limit=32&offset={{(page-1)*32}}&title={{key}}&includes[]=cover_art&hasAvailableChapters=true&includedTagsMode=AND&excludedTagsMode=OR{{buildQueryParams()}}`;\nresult;","exploreUrl":"@js:\neval(String(source.loginUrl));\nvar result = [];\nfunction push(title, url, size){\n    result.push({ title: title, url: url, style: { layout_flexGrow: 1, layout_flexBasisPercent: size } });\n}\nfunction head(t){\n    result.push({ title: t, type: 'text', style: { layout_flexGrow: 1, layout_flexBasisPercent: 1, layout_wrapBefore: true } });\n}\n// 图标表（与 jsLib 的 sorts 顺序一一对应）\nv