",\").map(x => getLanguage(x)).join(\" | \");\n    text.push(`\\n语言：${languages ? languages : \"所有语言\"}`);\n    const sortKey = sortField || \"\";\n    const sortStr = sorts.find(([_, or, ord]) =>\n        sortKey.includes(or) && ord === sortOrder)?. [0] || \"默认\";\n    text.push(`排序方式：${sortStr}`);\n\n    const contentStr = contentRating\n        .filter(([_, cr]) => target.includes(cr))\n        .map(([str]) => str)\n        .join(\" | \") || \"未设置\";\n    text.push(`内容等级：${contentStr}`);\n\n    text = text.join(\"\\n\");\n    java.toast(text);\n}\n\nfunction Put_contentRating(e) {\n    let tag = contentRating[e][1];\n    let tagStr = contentRating[e][0];\n    if (svb.contentRating.includes(tag)) {\n        java.toast(`\\n已取消展示【${tagStr}级】作品❌`);\n        svb.contentRating = svb.contentRating.filter(item => item !== tag);\n        java.log(JSON.stringify(svb.contentRating))\n    } else {\n        java.toast(`\\n已添加展示【${tagStr}级】作品✔️`);\n        svb.contentRating.push(tag);\n    }\n    source.setVariable(JSON.stringify(svb, null, \"\\t\"));\n}\n\nfunction Put_Sort(e) {\n    if (e !== \"默认\") {\n        sort_ = sorts[e][1] + \",\" + sorts[e][2];\n        point = sorts[e][0];\n    } else {\n        sort_ = \"\";\n        point = e;\n    }\n    svb.sort = sort_;\n    source.setVariable(JSON.stringify(svb, null, \"\\t\"));\n    java.toast(`\\n已切换排序为【${point}】`);\n}\n\nfunction login() {\n    svb.Language = source.getLoginInfoMap()[\"语言/缩写（英文逗号分隔多个语言）\"].toLowerCase();\n    source.setVariable(JSON.stringify(svb, null, \"\\t\"));\n}\n\n// ===== 下拉框联动（折叠）=====\n// 内容级别：名称 -> 索引\nfunction Put_RatingName(){\n  var v = '';\n  try{ v = (typeof result !== 'undefined' && result) ? String(result.get('内容级别') || '普通+粗略+限制') : '普通+粗略+限制'; }catch(e){}\n  var map = { '普通+粗略+限制':[0,1,2], '普通':[0], '粗略':[1], '限制':[2], '普通+粗略':[0,1] };\n  var idxs = map[v] || [0,1,2];\n  svb.contentRating = idxs.map(function(i){ return contentRating[i][1]; });\n  source.setVariable(JSON.stringify(svb));\